    res = {}
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        res[p] = cnt
    return res


def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    spf = build_spf(MAX_A)
    factors = []
